);

CREATE TABLE `Projects` (
  `project_id` NUMBER,
  `organisation_id` NUMBER REFERENCES `Organisations`(`organisation_id`),
  `project_details` TEXT,
  PRIMARY KEY (`project_id`)
);

CREATE TABLE `Research_Outcomes` (
  `outcome_code` TEXT,
  `outcome_description` TEXT,
  PRIMARY KEY (`outcome_code`)
);

CREATE TABLE `Research_Staff` (
  `staff_id` NUMBER,
  `employer_organisation_id` NUMBER REFERENCES `Organisations`(`organisation_id`),
  `staff_details` TEXT,
  PRIMARY KEY (`staff_id`)
);

CREATE TABLE `Staff_Roles` (
  `role_code` TEXT,
  `role_description` TEXT,
  PRIMARY KEY (`role_code`)
);

CREATE TABLE `Tasks` (
  `task_id` NUMBER,
  `project_id` NUMBER REFERENCES `Projects`(`project_id`),
  `task_details` TEXT,
  `eg Agree Objectives` TEXT,
  PRIMARY KEY (`task_id`)
